/**
 * Cloudflare Worker: serves the static build (via the ASSETS binding) and a tiny
 * progress-sync API backed by Workers KV.
 *
 *   GET  /api/sync/:code  → stored JSON (404 if none)
 *   PUT  /api/sync/:code  → store JSON body (≤ 1 MB)
 *
 * `code` is a random 32-hex string generated by the client; knowing it is the only
 * credential, exactly like a shared secret link.
 */
export interface Env {
  ASSETS: Fetcher;
  SYNC: KVNamespace;
}

export const MAX_BODY = 1_000_000;
const CODE_RE = /^[0-9a-f]{32}$/;

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } });

export async function handleSync(request: Request, env: Env, code: string): Promise<Response> {
  if (!CODE_RE.test(code)) return json({ error: 'invalid sync code' }, 400);
  const key = `sync:${code}`;
  if (request.method === 'GET') {
    const v = await env.SYNC.get(key);
    if (v === null) return json(null, 404);
    return new Response(v, { headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } });
  }
  if (request.method === 'PUT') {
    const len = Number(request.headers.get('content-length') ?? '0');
    if (len > MAX_BODY) return json({ error: 'too large' }, 413);
    const text = await request.text();
    if (text.length > MAX_BODY) return json({ error: 'too large' }, 413);
    let parsed: unknown;
    try {
      parsed = JSON.parse(text);
    } catch {
      return json({ error: 'invalid JSON' }, 400);
    }
    if (typeof parsed !== 'object' || parsed === null || !('courses' in parsed)) return json({ error: 'not a progress object' }, 400);
    // Keep data for a year after the last write.
    await env.SYNC.put(key, text, { expirationTtl: 60 * 60 * 24 * 365 });
    return new Response(null, { status: 204 });
  }
  return json({ error: 'method not allowed' }, 405);
}
